#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "kernel.h"

/* Component Handles */
static handle_t main_win = 0;
static handle_t h_btn_new = 0;
static handle_t h_btn_open = 0;
static handle_t h_btn_save = 0;
static handle_t h_lbl_filename = 0;
static handle_t h_text_buffer = 0;
static handle_t h_status_bar = 0;

/* Signal Callbacks */
static void on_new_file(void) {
    k_write_file("/dev/log", "[EVENT] on_new_file dispatched\n", 0);
    // Action logic for button btn_new
}

static void on_open_file(void) {
    k_write_file("/dev/log", "[EVENT] on_open_file dispatched\n", 0);
    // Action logic for button btn_open
}

static void on_save_file(void) {
    k_write_file("/dev/log", "[EVENT] on_save_file dispatched\n", 0);
    // Action logic for button btn_save
}

int main(int argc, char **argv) {
    main_win = k_create_window(800, 500, "ElfEditor");
    if (!main_win) return 1;

    /* toolbar (panel) */
    k_fill_rect(main_win, 0, 0, 800, 44, 0xFF111827);

    /* btn_new (button) */
    h_btn_new = k_create_button(main_win, 12, 8, 70, 28, "📄 New");

    /* btn_open (button) */
    h_btn_open = k_create_button(main_win, 88, 8, 70, 28, "📂 Open");

    /* btn_save (button) */
    h_btn_save = k_create_button(main_win, 164, 8, 70, 28, "💾 Save");

    /* sep1 (separator) */
    k_fill_rect(main_win, 245, 8, 2, 28, 0xFF374151);

    /* lbl_filename (label) */
    h_lbl_filename = k_create_label(main_win, 260, 12, "/mnt/Apps/document.txt");

    /* text_buffer (textarea) */
    h_text_buffer = k_create_textfield(main_win, 12, 56, 776);
    k_textfield_setup(h_text_buffer, 4096, 0, 0);
    k_textfield_set_multiline(h_text_buffer, 1);
    k_set_text(h_text_buffer, "/* Windose OS Kernel v10 Source File */\n#include <stdio.h>\n#include \"kernel.h\"\n\nint main(int argc, char **argv) {\n    printf(\"Hello from native ELF!\n\");\n    return 0;\n}");

    /* status_bar (statusbar) */
    h_status_bar = k_statusbar_create(main_win, 0, 472, 800);
    k_status_add_panel(h_status_bar, "Ln 7, Col 1 | UTF-8 | Unix (LF) | Windose C99", 800);

    /* Main Windose Event Loop */
    for (;;) {
        Event e;
        while (k_poll_event(&e)) {
            if (e.type == EV_CLOSE && e.handle == main_win) {
                k_close(main_win);
                return 0;
            }
            if (e.type == EV_CLICK) {
                if (e.handle == h_btn_new) {
                    on_new_file();
                }
                if (e.handle == h_btn_open) {
                    on_open_file();
                }
                if (e.handle == h_btn_save) {
                    on_save_file();
                }
            }
        }
        k_sleep(10); // Prevent 100% CPU starvation
    }
}